4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Flags a soft (non-hard) duplicate on the owner being created. A hard duplicate — the same
9	 * {@link OwnerIdentityKey} as an existing owner — is already rejected with 409 by
10	 * {@link EnsureUniqueIdentity} before this step runs, so any owner reaching here is not a hard
11	 * duplicate. This step then looks for an existing owner that shares this owner's normalized last name
12	 * and postcode but has a <em>different</em> telephone: such an owner is still created, but is marked
13	 * {@code possibleDuplicate = true} with {@code possibleDuplicateOf} set to the matching owner's id.
14	 * When no such owner exists, {@code possibleDuplicate} is {@code false}.
15	 *
16	 * <p>Runs after {@link BuildOwner} (so the owner already carries the normalized E.164 telephone and
17	 * the postcode) and before {@link SaveOwner}.
18	 */
19	public class AssignPossibleDuplicate {
20	
21	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
22	        owner.setPossibleDuplicate(false);
23	        owner.setPossibleDuplicateOf(null);
24	
25	        String postcode = normalizePostcode(owner.getPostcode());
26	        if (postcode == null) {
27	            return; // no postcode means it cannot share a postcode with anyone
28	        }
29	        String lastName = OwnerIdentityKey.normalizeName(owner.getLastName());
30	        String telephone = E164Telephone.toE164OrNull(owner.getTelephone());
31	
32	        for (Owner existing : ownerRepository.findAll()) {
33	            if (!postcode.equals(normalizePostcode(existing.getPostcode()))) {
34	                continue;
35	            }
36	            if (!lastName.equals(OwnerIdentityKey.normalizeName(existing.getLastName()))) {
37	                continue;
38	            }
39	            String existingTelephone = E164Telephone.toE164OrNull(existing.getTelephone());
40	            if (telephone != null && telephone.equals(existingTelephone)) {
41	                continue; // same telephone is a hard duplicate concern, not a soft match
42	            }
43	            owner.setPossibleDuplicate(true);
44	            owner.setPossibleDuplicateOf(existing.getId());
45	            return;
46	        }
47	    }
48	
49	    private static String normalizePostcode(String postcode) {
50	        if (postcode == null) {
51	            return null;
52	        }
53	        String trimmed = postcode.trim();
54	        return trimmed.isEmpty() ? null : trimmed;
55	    }
56	}
