3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	import net.officefloor.plugin.variable.Val;
8	import org.springframework.samples.petclinic.model.Owner;
9	
10	/**
11	 * Assigns the owner's {@code customerCode}, formatted {@code <REGION>-<HASH8>} where REGION is the
12	 * region derived from the owner's postcode (see {@link CustomerCodeRegion}) and HASH8 is the first
13	 * eight upper-case hex characters of SHA-256 over the concatenation of the owner's normalized (E.164)
14	 * telephone and last name (e.g. {@code NSW-1A2B3C4D}). There is no sequence number, so the code is
15	 * stable for a given telephone/last-name/region and does not depend on how many owners already exist.
16	 * Every value built from the customerCode — the membership number, its check digit, the create audit
17	 * line and the derived locality — follows this region-and-hash identity.
18	 */
19	public class AssignCustomerCode {
20	
21	    public void service(@Val Owner owner) {
22	        owner.setCustomerCode(CustomerCodeRegion.of(owner) + "-" + hash8(owner));
23	    }
24	
25	    /** First eight upper-case hex characters of SHA-256(normalizedTelephone + lastName). */
26	    private static String hash8(Owner owner) {
27	        // The stored telephone is already E.164 (see NormalizeOwnerTelephone); re-normalizing is
28	        // idempotent and falls back to the stored value if it somehow cannot be parsed.
29	        String normalizedTelephone = E164Telephone.toE164OrNull(owner.getTelephone());
30	        if (normalizedTelephone == null) {
31	            normalizedTelephone = owner.getTelephone() == null ? "" : owner.getTelephone();
32	        }
33	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
34	        try {
35	            byte[] digest = MessageDigest.getInstance("SHA-256")
36	                    .digest((normalizedTelephone + lastName).getBytes(StandardCharsets.UTF_8));
37	            StringBuilder sb = new StringBuilder(8);
38	            for (int i = 0; i < 4; i++) {
39	                sb.append(String.format("%02X", digest[i]));
40	            }
41	            return sb.toString();
42	        }
43	        catch (NoSuchAlgorithmException e) {
44	            throw new IllegalStateException("SHA-256 unavailable", e);
45	        }
46	    }
47	}
